<section class="mt-5 card"><h2 class="font-semibold">Safe timeline</h2><div class="mt-4 space-y-3">@forelse($execution->stepExecutions as $step)<article class="rounded-xl border p-4"><div class="flex flex-wrap gap-3"><strong>{{$step->step_key}}</strong><x-badge>{{str($step->status->value)->headline()}}</x-badge><span class="text-sm text-[var(--text-muted)]">{{str($step->step_type)->headline()}} · attempt {{$step->attempt_number}}</span></div>@php($safe=collect($step->output_snapshot??[])->only(['result','selected_step_key','waiting_until','message_uuid','message_status','template_version_uuid','changed','resource_uuid','changed_fields','reason']))@if($safe->isNotEmpty())<p class="mt-2 text-sm">@foreach($safe as $key=>$value)<span class="mr-4"><span class="text-[var(--text-muted)]">{{str($key)->replace('_',' ')->headline()}}:</span> {{is_array($value)?implode(', ',$value):(is_bool($value)?($value?'Yes':'No'):$value)}}</span>@endforeach</p>@endif @if($step->failure_code)<p class="mt-2 text-sm text-red-500">{{$step->failure_code}}</p>@endif</article>@empty<p>No steps started.</p>@endforelse</div></section><p class="mt-4 text-sm text-[var(--text-muted)]">Raw context, configuration, personal data, message content, and secrets are hidden.</p></x-layouts.platform>
